	private static PatternPlan pattern(Term root) {
		return new PatternPlan(root, Term.slot(1), Term.slot(2), Term.unbound(), ContextConstraint.UNRESTRICTED,
				false, 16D);
	}

	private static List<Long> output(long root, long predicate, long neighbor) {
		return List.of(root, predicate, neighbor);
	}

	private static ValuesRow input(long root, long predicate) {
		return new ValuesRow(new int[] { 0, 1 }, new long[] { root, predicate });
	}

	private static List<List<Long>> collect(BatchCursor cursor) throws IOException {
		NativeBatch output = new NativeBatch(3, 1);
		List<List<Long>> rows = new ArrayList<>();
		while (cursor.fill(output) > 0) {
			for (int i = 0; i < output.selectedCount; i++) {
				int lane = output.selection[i];
				rows.add(output(output.get(0, lane), output.get(1, lane), output.get(2, lane)));
			}
		}
		return rows;
	}

